class Solution {
    public int appendCharacters(String s, String t) {
        int matched = 0;
        for (int i = 0; i < s.length() && matched < t.length(); i++) {
            if (s.charAt(i) == t.charAt(matched)) {
                matched++;
            }
        }
        return t.length() - matched;
    }
}

class Solution {
    public int appendCharacters(String s, String t) {
        int position = -1;
        int matched = 0;
        while (matched < t.length()) {
            position = s.indexOf(t.charAt(matched), position + 1);
            if (position == -1) {
                break;
            }
            matched++;
        }
        return t.length() - matched;
    }
}

import java.util.*;

class Solution {
    public int appendCharacters(String s, String t) {
        List<Integer>[] positions = new ArrayList[26];
        for (int i = 0; i < 26; i++) {
            positions[i] = new ArrayList<>();
        }
        for (int i = 0; i < s.length(); i++) {
            positions[s.charAt(i) - 'a'].add(i);
        }

        int previous = -1;
        for (int matched = 0; matched < t.length(); matched++) {
            List<Integer> list = positions[t.charAt(matched) - 'a'];
            int index = firstGreaterThan(list, previous);
            if (index == list.size()) {
                return t.length() - matched;
            }
            previous = list.get(index);
        }
        return 0;
    }

    private int firstGreaterThan(List<Integer> list, int value) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (list.get(mid) <= value) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

import java.util.*;

class Solution {
    public int appendCharacters(String s, String t) {
        ArrayDeque<Integer>[] positions = new ArrayDeque[26];
        for (int i = 0; i < 26; i++) {
            positions[i] = new ArrayDeque<>();
        }
        for (int i = 0; i < s.length(); i++) {
            positions[s.charAt(i) - 'a'].offer(i);
        }

        int previous = -1;
        for (int matched = 0; matched < t.length(); matched++) {
            ArrayDeque<Integer> queue = positions[t.charAt(matched) - 'a'];
            while (!queue.isEmpty() && queue.peek() <= previous) {
                queue.poll();
            }
            if (queue.isEmpty()) {
                return t.length() - matched;
            }
            previous = queue.poll();
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int appendCharacters(String s, String t) {
        int n = s.length();
        int[][] next = new int[n + 1][26];
        Arrays.fill(next[n], -1);
        for (int i = n - 1; i >= 0; i--) {
            System.arraycopy(next[i + 1], 0, next[i], 0, 26);
            next[i][s.charAt(i) - 'a'] = i;
        }

        int position = 0;
        for (int matched = 0; matched < t.length(); matched++) {
            int found = next[position][t.charAt(matched) - 'a'];
            if (found == -1) {
                return t.length() - matched;
            }
            position = found + 1;
        }
        return 0;
    }
}
